import XCTest
import CryptoKit
#if canImport(Security)
import Security
#endif
@testable import QAudionEngine

/// The call-key priority of docs/security/CALL_KEY_PRIORITY.md: the order of the pre-shared keys, which is the
/// order of the caller's advert and the order of the list in Key management.
///
/// The conformance table is `Crypto/Resources/call-key-priority-cases.tsv`, a byte-for-byte copy of the file the
/// Android tests run too (generated by `docs/security/gen_key_priority_cases.py`). Every row is run through
/// `CallKeyPriority`, the one type the real list uses, three times: operation by operation on the type itself, with
/// the list rebuilt from the keys the vault holds after every step, and through `CallKeyPriorityStore` over an
/// in-memory backing with a restart after every step.
///
/// The operations are `+X` new key, `-X` delete, `^X` up, `vX` down, `~X>Y` Y stored as the replacement of X (X is the
/// highest-ranked key of its device) and `!Y` Y finalized (docs/security/CALL_KEY_PRIORITY.md section 4a).
///
/// Keychain-free: the store runs over an in-memory backing, because the CI simulator refuses real Keychain access.
final class CallKeyPriorityTests: XCTestCase {

    // MARK: - The shared table

    private struct Case {
        let name: String
        let operations: String
        let expectedOrder: String
    }

    /// SHA-256 of the table. A change to the table must be the same change in both repositories.
    private static let tableSha256 = "e57341ed40fb3a403a97d5429aeb7880d0270274ad501367bc85339af0884145"

    private static let columns = ["name", "operations", "expected_order", "description"]

    private func tableData() throws -> Data {
        let url = try XCTUnwrap(
            Bundle.module.url(forResource: "call-key-priority-cases", withExtension: "tsv"),
            "call-key-priority-cases.tsv is missing from the test bundle")
        return try Data(contentsOf: url)
    }

    /// The rows of the table. Lines end with LF or CRLF (`isNewline` is true for both).
    private func parseCases(_ data: Data) throws -> [Case] {
        let text = try XCTUnwrap(String(data: data, encoding: .utf8), "the table is not UTF-8")
        var rows: [[String]] = []
        for rawLine in text.split(whereSeparator: \.isNewline) {
            let line = String(rawLine)
            if line.isEmpty || line.hasPrefix("#") { continue }
            rows.append(line.components(separatedBy: "\t"))
        }
        let header = try XCTUnwrap(rows.first, "the table has no header")
        XCTAssertEqual(header, Self.columns, "the columns of the table changed")
        var cases: [Case] = []
        for row in rows.dropFirst() {
            XCTAssertEqual(row.count, Self.columns.count, "a row of the table has the wrong number of columns: \(row)")
            guard row.count == Self.columns.count else { continue }
            cases.append(Case(name: row[0], operations: row[1], expectedOrder: row[2]))
        }
        return cases
    }

    private func group(of name: String) throws -> CallKeyPriority.Group {
        switch name.first {
        case "H": return .hwOnly
        case "K": return .kms
        case "O": return .other
        default:
            XCTFail("a key name must start with H, K or O: \(name)")
            return .other
        }
    }

    func testTheTableIsTheSharedOne() throws {
        let digest = SHA256.hash(data: try tableData()).map { String(format: "%02x", $0) }.joined()
        XCTAssertEqual(digest, Self.tableSha256, "call-key-priority-cases.tsv is not the shared table")
    }

    /// The two names of a `~X>Y` operation.
    private func replacement(_ rest: String, _ testCase: Case) throws -> (old: String, new: String) {
        let names = rest.components(separatedBy: ">")
        XCTAssertEqual(names.count, 2, "\(testCase.name): \(rest) is not X>Y")
        return (names[0], names.count == 2 ? names[1] : "")
    }

    func testEveryRowOfTheTableGivesItsExpectedOrder() throws {
        let cases = try parseCases(try tableData())
        XCTAssertEqual(cases.count, 43, "the table changed its number of rows")
        for testCase in cases {
            var list = CallKeyPriority()
            var devices: [String: String] = [:]
            for operation in testCase.operations.split(separator: " ") {
                let kind = operation.first
                let key = String(operation.dropFirst())
                switch kind {
                case "+":
                    list.add(id: key, group: try group(of: key))
                    devices[key] = key
                case "-": list.remove(key)
                case "^": list.moveUp(key)
                case "v": list.moveDown(key)
                case "~":
                    let names = try replacement(key, testCase)
                    let device = try XCTUnwrap(devices[names.old], "\(testCase.name): \(operation) replaces a key not held")
                    XCTAssertEqual(list.entries.first(where: { $0.device == device })?.id, names.old,
                                   "\(testCase.name): \(operation): X must be the highest-ranked key of its device")
                    list.storeAsReplacement(id: names.new, device: device)
                    devices[names.new] = device
                case "!":
                    list.finalize(key)
                default: XCTFail("\(testCase.name): unknown operation \(operation)")
                }
            }
            XCTAssertEqual(list.ids.joined(separator: " "), testCase.expectedOrder,
                           "\(testCase.name): \(testCase.operations)")
        }
    }

    /// The app never replays operations: it keeps the order and the marks, and after each key arrives or leaves it
    /// rebuilds the list from the keys the vault holds (`CallKeyPriority.reconciled`). That path must give the table's
    /// result too, with every key arriving at a later time than the one before.
    func testEveryRowOfTheTableGivesItsExpectedOrderWhenTheListIsRebuiltFromTheVault() throws {
        let cases = try parseCases(try tableData())
        for testCase in cases {
            var held: [CallKeyPriority.Candidate] = []
            var devices: [String: String] = [:]
            var stored: CallKeyPriority.Stored?
            var list = CallKeyPriority()
            var step = 0
            for operation in testCase.operations.split(separator: " ") {
                step += 1
                let kind = operation.first
                let key = String(operation.dropFirst())
                switch kind {
                case "+":
                    held.append(CallKeyPriority.Candidate(
                        id: key, group: try group(of: key), createdAt: Date(timeIntervalSince1970: Double(step))))
                    devices[key] = key
                    list = CallKeyPriority.reconciled(stored: stored, candidates: held)
                case "-":
                    held.removeAll(where: { $0.id == key })
                    list = CallKeyPriority.reconciled(stored: stored, candidates: held)
                case "^":
                    list = CallKeyPriority.reconciled(stored: stored, candidates: held)
                    list.moveUp(key)
                case "v":
                    list = CallKeyPriority.reconciled(stored: stored, candidates: held)
                    list.moveDown(key)
                case "~":
                    // The new key is a new vault entry of the same device, with a date later than every key before
                    // it: the list meets it as an arrival and stores it as the replacement.
                    let names = try replacement(key, testCase)
                    let device = try XCTUnwrap(devices[names.old], "\(testCase.name): \(operation) replaces a key not held")
                    held.append(CallKeyPriority.Candidate(
                        id: names.new, group: .other, createdAt: Date(timeIntervalSince1970: Double(step)), device: device))
                    devices[names.new] = device
                    list = CallKeyPriority.reconciled(stored: stored, candidates: held)
                case "!":
                    list = CallKeyPriority.reconciled(stored: stored, candidates: held)
                    let removed = list.finalize(key)
                    held.removeAll(where: { removed.contains($0.id) })
                default:
                    XCTFail("\(testCase.name): unknown operation \(operation)")
                }
                // What is stored survives a restart: the next step starts from the decoded form.
                let data = try XCTUnwrap(list.stored.encoded(), "\(testCase.name): the list does not encode")
                stored = try XCTUnwrap(CallKeyPriority.Stored.decode(data), "\(testCase.name): the list does not decode")
            }
            XCTAssertEqual(list.ids.joined(separator: " "), testCase.expectedOrder,
                           "\(testCase.name) (rebuilt from the vault): \(testCase.operations)")
        }
    }

    /// The same table through `CallKeyPriorityStore`, the type the app calls: the vault is the `Held` list, a new
    /// store over the same backing starts every step (a restart of the app), `finalize` deletes from the vault.
    func testEveryRowOfTheTableGivesItsExpectedOrderThroughTheStoreWithARestartAfterEveryStep() throws {
        let cases = try parseCases(try tableData())
        for testCase in cases {
            let backing = MemoryBacking()
            let held = Held()
            var devices: [String: String] = [:]
            var step = 0
            for operation in testCase.operations.split(separator: " ") {
                step += 1
                let store = makeStore(backing, held)
                let kind = operation.first
                let key = String(operation.dropFirst())
                switch kind {
                case "+":
                    held.add(key, try group(of: key), at: Double(step))
                    devices[key] = key
                    store.syncWithVault()
                case "-":
                    held.remove(key)
                    store.syncWithVault()
                case "^":
                    XCTAssertTrue(store.moveUp(key).saved, testCase.name)
                case "v":
                    XCTAssertTrue(store.moveDown(key).saved, testCase.name)
                case "~":
                    let names = try replacement(key, testCase)
                    let device = try XCTUnwrap(devices[names.old], "\(testCase.name): \(operation) replaces a key not held")
                    held.add(names.new, .other, at: Double(step), device: device)
                    devices[names.new] = device
                    store.syncWithVault()
                case "!":
                    XCTAssertTrue(store.finalize(key).complete, "\(testCase.name): \(operation)")
                default:
                    XCTFail("\(testCase.name): unknown operation \(operation)")
                }
            }
            XCTAssertEqual(makeStore(backing, held).current().ids.joined(separator: " "), testCase.expectedOrder,
                           "\(testCase.name) (through the store): \(testCase.operations)")
            XCTAssertEqual(held.items.map { $0.id }.sorted(), makeStore(backing, held).current().ids.sorted(),
                           "\(testCase.name): the vault and the list hold the same keys")
        }
    }

    // MARK: - Groups

    func testGroupsFollowTheOriginAndTheClass() {
        XCTAssertEqual(CallKeyPriority.group(origin: .kms, keyClass: .hwOnly), .hwOnly)
        XCTAssertEqual(CallKeyPriority.group(origin: .manual, keyClass: .hwOnly), .hwOnly)
        XCTAssertEqual(CallKeyPriority.group(origin: .kms, keyClass: .shared), .kms)
        XCTAssertEqual(CallKeyPriority.group(origin: .kms, keyClass: .swOnly), .kms)
        XCTAssertEqual(CallKeyPriority.group(origin: .nfc, keyClass: .shared), .other)
        XCTAssertEqual(CallKeyPriority.group(origin: .proximity, keyClass: .shared), .other)
        XCTAssertEqual(CallKeyPriority.group(origin: .manual, keyClass: .shared), .other)
    }

    // MARK: - First run (section 5)

    func testFirstRunOrdersHwOnlyThenKmsThenOthersAndDoesNotDependOnTheInputOrder() {
        func candidate(_ id: String, _ group: CallKeyPriority.Group, _ seconds: Double?) -> CallKeyPriority.Candidate {
            CallKeyPriority.Candidate(id: id, group: group, createdAt: seconds.map { Date(timeIntervalSince1970: $0) })
        }
        let candidates = [
            candidate("O1", .other, 30),
            candidate("K2", .kms, 90),
            candidate("H1", .hwOnly, 10),
            candidate("O3", .other, nil),
            candidate("K1", .kms, 20),
            candidate("H2", .hwOnly, 50),
            candidate("O2", .other, 10),
        ]
        // H and K newest first, O oldest first, a key with no date after the dated ones of its group.
        let expected = ["H2", "H1", "K2", "K1", "O2", "O1", "O3"]
        XCTAssertEqual(CallKeyPriority.firstRun(candidates).ids, expected)
        XCTAssertEqual(CallKeyPriority.firstRun(candidates.reversed()).ids, expected)
        XCTAssertFalse(CallKeyPriority.firstRun(candidates).entries.contains(where: { $0.placedByHand }),
                       "no key starts placed by hand")
        XCTAssertEqual(CallKeyPriority.reconciled(stored: nil, candidates: candidates).ids, expected,
                       "nothing stored: the first run")
    }

    func testFirstRunBreaksTiesByIdAndIgnoresADuplicateId() {
        let t = Date(timeIntervalSince1970: 5)
        let candidates = [
            CallKeyPriority.Candidate(id: "b", group: .kms, createdAt: t),
            CallKeyPriority.Candidate(id: "a", group: .kms, createdAt: t),
            CallKeyPriority.Candidate(id: "a", group: .other, createdAt: t),
        ]
        XCTAssertEqual(CallKeyPriority.firstRun(candidates).ids, ["a", "b"])
    }

    // MARK: - Rebuilding from what is stored

    func testRebuildingDropsADeletedKeyWithItsMarkAndAddsANewKeyByTheRule() {
        let t = { (seconds: Double) in Date(timeIntervalSince1970: seconds) }
        var list = CallKeyPriority()
        list.add(id: "K1", group: .kms)
        list.add(id: "O1", group: .other)
        list.moveUp("O1")
        XCTAssertEqual(list.ids, ["O1", "K1"])
        XCTAssertTrue(list.isPlacedByHand("O1"))

        // K1 is gone from the vault, K2 arrived: O1 stays first (placed), K2 goes below it.
        let held = [
            CallKeyPriority.Candidate(id: "O1", group: .other, createdAt: t(1)),
            CallKeyPriority.Candidate(id: "K2", group: .kms, createdAt: t(9)),
        ]
        let rebuilt = CallKeyPriority.reconciled(stored: list.stored, candidates: held)
        XCTAssertEqual(rebuilt.ids, ["O1", "K2"])
        XCTAssertTrue(rebuilt.isPlacedByHand("O1"))
        XCTAssertFalse(rebuilt.isPlacedByHand("K2"))
    }

    func testRebuildingAddsSeveralNewKeysOldestFirstAsIfTheyArrivedOneByOne() {
        let t = { (seconds: Double) in Date(timeIntervalSince1970: seconds) }
        let stored = CallKeyPriority.Stored(keys: [CallKeyPriority.Stored.Key(id: "K0", placed: false)])
        let held = [
            CallKeyPriority.Candidate(id: "K0", group: .kms, createdAt: t(1)),
            CallKeyPriority.Candidate(id: "K2", group: .kms, createdAt: t(30)),
            CallKeyPriority.Candidate(id: "K1", group: .kms, createdAt: t(20)),
            CallKeyPriority.Candidate(id: "O1", group: .other, createdAt: t(25)),
        ]
        // K1 (20) goes above K0, O1 (25) at the end, K2 (30) above K1.
        XCTAssertEqual(CallKeyPriority.reconciled(stored: stored, candidates: held).ids, ["K2", "K1", "K0", "O1"])
    }

    func testRebuildingWhenNothingStoredSurvivesIsTheFirstRun() {
        let stored = CallKeyPriority.Stored(keys: [CallKeyPriority.Stored.Key(id: "gone", placed: true)])
        let held = [
            CallKeyPriority.Candidate(id: "O1", group: .other, createdAt: Date(timeIntervalSince1970: 1)),
            CallKeyPriority.Candidate(id: "K1", group: .kms, createdAt: Date(timeIntervalSince1970: 2)),
        ]
        let rebuilt = CallKeyPriority.reconciled(stored: stored, candidates: held)
        XCTAssertEqual(rebuilt.ids, ["K1", "O1"])
        XCTAssertFalse(rebuilt.entries.contains(where: { $0.placedByHand }))
    }

    func testAMoveMarksOnlyTheMovedKeyAndAnEdgeMoveMarksToo() {
        var list = CallKeyPriority()
        list.add(id: "K1", group: .kms)
        list.add(id: "O1", group: .other)
        XCTAssertFalse(list.moveUp("K1"), "the first key cannot go up")
        XCTAssertTrue(list.isPlacedByHand("K1"), "an edge move still marks the key")
        XCTAssertFalse(list.isPlacedByHand("O1"))
        XCTAssertFalse(list.moveDown("O1"), "the last key cannot go down")
        XCTAssertTrue(list.isPlacedByHand("O1"))
        XCTAssertFalse(list.moveUp("missing"), "a key that is not in the list does nothing")
        XCTAssertEqual(list.ids, ["K1", "O1"])
    }

    // MARK: - Stored form

    func testTheStoredFormRoundTripsAndRefusesWhatIsNotOfThisVersion() throws {
        var list = CallKeyPriority()
        list.add(id: "K1", group: .kms)
        list.add(id: "O1", group: .other)
        list.moveUp("O1")
        let data = try XCTUnwrap(list.stored.encoded())
        let decoded = try XCTUnwrap(CallKeyPriority.Stored.decode(data))
        XCTAssertEqual(decoded, list.stored)
        XCTAssertEqual(decoded.keys.map { $0.id }, ["O1", "K1"])
        XCTAssertEqual(decoded.keys.map { $0.placed }, [true, false])

        XCTAssertNil(CallKeyPriority.Stored.decode(Data("not json".utf8)))
        XCTAssertNil(CallKeyPriority.Stored.decode(Data()))
        let otherVersion = CallKeyPriority.Stored(version: 99, keys: [])
        XCTAssertNil(CallKeyPriority.Stored.decode(try XCTUnwrap(otherVersion.encoded())))
    }

    // MARK: - The store

    private final class MemoryBacking: CallKeyPriorityBacking {
        var data: Data?
        var unreadable = false
        /// The Keychain refuses the write: nothing is stored and `write` says so.
        var failWrites = false
        private(set) var writes = 0

        func read() -> CallKeyPriorityStoredRead {
            if unreadable { return .unreadable }
            if let data { return .found(data) }
            return .absent
        }

        func write(_ data: Data) -> Bool {
            if failWrites { return false }
            self.data = data
            writes += 1
            return true
        }
    }

    /// The keys "in the vault" of a store test: a store reads them through the same closure the real one reads the
    /// Keychain with.
    private final class Held {
        var items: [CallKeyPriority.Candidate] = []

        func add(_ id: String, _ group: CallKeyPriority.Group, at seconds: Double, device: String? = nil) {
            items.append(CallKeyPriority.Candidate(
                id: id, group: group, createdAt: Date(timeIntervalSince1970: seconds), device: device))
        }

        func remove(_ id: String) {
            items.removeAll(where: { $0.id == id })
        }
    }

    private func makeStore(_ backing: MemoryBacking, _ held: Held) -> CallKeyPriorityStore {
        CallKeyPriorityStore(backing: backing, candidates: { held.items }, deleteKey: { id in
            held.remove(id)
            return true
        })
    }

    func testTheStoreWritesTheFirstRunListOnceAndNothingWhenNothingChanged() {
        let backing = MemoryBacking()
        let held = Held()
        held.add("O1", .other, at: 1)
        held.add("K1", .kms, at: 2)
        let store = makeStore(backing, held)
        XCTAssertEqual(store.current().ids, ["K1", "O1"])
        XCTAssertEqual(store.current().ids, ["K1", "O1"])
        store.syncWithVault()
        XCTAssertEqual(backing.writes, 1)
    }

    func testTheStoreWritesNothingForAnEmptyVault() {
        let backing = MemoryBacking()
        let store = makeStore(backing, Held())
        XCTAssertEqual(store.current().ids, [])
        XCTAssertEqual(backing.writes, 0)
    }

    func testAKeyMovedAboveKmsStaysAboveWhenNewKmsKeysArriveAndAfterARestart() {
        let backing = MemoryBacking()
        let held = Held()
        held.add("O1", .other, at: 1)
        held.add("K1", .kms, at: 2)
        var store = makeStore(backing, held)
        XCTAssertEqual(store.current().ids, ["K1", "O1"])

        XCTAssertEqual(store.moveUp("O1").list.ids, ["O1", "K1"])

        held.add("K2", .kms, at: 3)
        store.syncWithVault()
        XCTAssertEqual(store.current().ids, ["O1", "K2", "K1"])

        // A new store over the same backing is a restart of the app.
        store = makeStore(backing, held)
        XCTAssertEqual(store.current().ids, ["O1", "K2", "K1"])
        held.add("K3", .kms, at: 4)
        XCTAssertEqual(store.current().ids, ["O1", "K3", "K2", "K1"])
    }

    // MARK: - Pairing again with the same device (section 4a)

    private let deviceHex = "0123456789abcdef"

    private func inPersonName(_ method: String, _ device: String, _ fingerprintHead: String) -> String {
        "\(method)-\(device)-\(fingerprintHead)"
    }

    /// Store: the new key arrives as a second entry of the device, takes the place and the mark of the earlier one,
    /// which stays directly below it. Nothing is deleted. The place survives a restart.
    func testANewKeyOfTheSameDeviceTakesThePlaceAndMarkOfTheEarlierKeyAndTheEarlierOneStaysLive() {
        let backing = MemoryBacking()
        let held = Held()
        let first = inPersonName("prox", deviceHex, "11111111")
        let second = inPersonName("prox", deviceHex, "22222222")
        held.add(first, .other, at: 1, device: CallKeyPriority.inPersonDevice(ofAccount: first))
        var store = makeStore(backing, held)
        XCTAssertEqual(store.moveUp(first).list.ids, [first])

        held.add(second, .other, at: 3, device: CallKeyPriority.inPersonDevice(ofAccount: second))
        store.syncWithVault()
        XCTAssertEqual(store.current().ids, [second, first])
        XCTAssertTrue(store.current().isPlacedByHand(second), "the mark moved to the new key")
        XCTAssertFalse(store.current().isPlacedByHand(first))
        XCTAssertEqual(store.current().pending(second), .waiting)
        XCTAssertEqual(store.current().pending(first), .retiring)
        XCTAssertEqual(held.items.count, 2, "storing deletes nothing")

        store = makeStore(backing, held)
        XCTAssertEqual(store.current().ids, [second, first])
        XCTAssertEqual(store.current().pending(second), .waiting)

        // The mark still does its work: a first KMS key goes below the new key, above the unmarked earlier key.
        held.add("K1", .kms, at: 4)
        XCTAssertEqual(store.current().ids, [second, "K1", first])
        XCTAssertEqual(store.current().pending("K1"), .none)
    }

    func testAKeyOfTheSameDeviceInTheDefaultPlaceStaysBelowKmsAndEverythingIsLive() {
        let backing = MemoryBacking()
        let held = Held()
        let first = inPersonName("nfc", deviceHex, "11111111")
        let second = inPersonName("nfc", deviceHex, "22222222")
        held.add("K1", .kms, at: 1)
        held.add(first, .other, at: 2, device: CallKeyPriority.inPersonDevice(ofAccount: first))
        let store = makeStore(backing, held)
        XCTAssertEqual(store.current().ids, ["K1", first])
        held.add(second, .other, at: 3, device: CallKeyPriority.inPersonDevice(ofAccount: second))
        XCTAssertEqual(store.current().ids, ["K1", second, first], "both are in the advert, the new one first")
    }

    /// Finalize deletes the earlier keys of that device from the vault and the list, and only those.
    func testFinalizeDeletesTheEarlierKeysOfTheDeviceFromTheVaultAndKeepsTheRest() {
        let backing = MemoryBacking()
        let held = Held()
        let deviceName = "prox-" + deviceHex
        let first = inPersonName("prox", deviceHex, "11111111")
        let second = inPersonName("prox", deviceHex, "22222222")
        let third = inPersonName("prox", deviceHex, "33333333")
        let otherDevice = inPersonName("prox", "fedcba9876543210", "44444444")
        held.add("K1", .kms, at: 1)
        held.add(first, .other, at: 2, device: deviceName)
        held.add(otherDevice, .other, at: 3, device: CallKeyPriority.inPersonDevice(ofAccount: otherDevice))
        let store = makeStore(backing, held)
        XCTAssertEqual(store.current().ids, ["K1", first, otherDevice])
        held.add(second, .other, at: 4, device: deviceName)
        XCTAssertEqual(store.current().ids, ["K1", second, first, otherDevice])
        held.add(third, .other, at: 5, device: deviceName)
        XCTAssertEqual(store.current().ids, ["K1", third, second, first, otherDevice])

        // The second key is the one proven: the first goes, the third (stored after it) stays.
        let result = store.finalize(second)
        XCTAssertEqual(result, CallKeyPriorityFinalize(deleted: [first], complete: true))
        XCTAssertEqual(store.current().ids, ["K1", third, second, otherDevice])
        XCTAssertEqual(Set(held.items.map { $0.id }), Set(["K1", third, second, otherDevice]))
        XCTAssertEqual(store.current().pending(third), .waiting)

        XCTAssertEqual(store.finalize(second), CallKeyPriorityFinalize(deleted: [], complete: true), "twice changes nothing")
        XCTAssertEqual(store.finalize(third).deleted, [second])
        XCTAssertEqual(store.current().ids, ["K1", third, otherDevice])
        XCTAssertEqual(store.current().pending(third), .none)
    }

    func testFinalizingAKeyThatIsNotInTheListOrBelongsToNoDeviceDeletesNothing() {
        let backing = MemoryBacking()
        let held = Held()
        held.add("K1", .kms, at: 1)
        held.add("K2", .kms, at: 2)
        let store = makeStore(backing, held)
        XCTAssertEqual(store.finalize("K2"), CallKeyPriorityFinalize(deleted: [], complete: true))
        XCTAssertEqual(store.finalize("missing"), CallKeyPriorityFinalize(deleted: [], complete: true))
        XCTAssertEqual(held.items.count, 2)
    }

    func testFinalizeDeletesNothingWhenTheStoredListCannotBeReadOrAKeyCannotBeDeleted() {
        let backing = MemoryBacking()
        let held = Held()
        let first = inPersonName("nfc", deviceHex, "11111111")
        let second = inPersonName("nfc", deviceHex, "22222222")
        held.add(first, .other, at: 1, device: "nfc-" + deviceHex)
        let store = makeStore(backing, held)
        XCTAssertEqual(store.current().ids, [first])
        held.add(second, .other, at: 2, device: "nfc-" + deviceHex)
        XCTAssertEqual(store.current().ids, [second, first])

        backing.unreadable = true
        XCTAssertEqual(store.finalize(second), CallKeyPriorityFinalize(deleted: [], complete: false))
        XCTAssertEqual(held.items.count, 2, "without the stored sequence nothing is deleted")
        backing.unreadable = false

        let refusing = CallKeyPriorityStore(backing: backing, candidates: { held.items }, deleteKey: { _ in false })
        XCTAssertEqual(refusing.finalize(second), CallKeyPriorityFinalize(deleted: [], complete: false))
        XCTAssertEqual(refusing.current().ids, [second, first], "a key the vault could not delete stays in the list")
        XCTAssertEqual(store.finalize(second), CallKeyPriorityFinalize(deleted: [first], complete: true))
    }

    /// An entry written before the two steps existed is named `nfc-<16 hex>` and its stored list has no sequence
    /// numbers: it works as before and counts as stored first.
    func testAnEntryWithTheOldNameAndAStoredListWithoutSequenceNumbersKeepsWorkingAndIsStoredFirst() throws {
        let legacy = "nfc-" + deviceHex
        let fresh = inPersonName("nfc", deviceHex, "22222222")
        XCTAssertEqual(CallKeyPriority.inPersonDevice(ofAccount: legacy), "nfc-" + deviceHex)
        XCTAssertEqual(CallKeyPriority.inPersonDevice(ofAccount: fresh), "nfc-" + deviceHex)

        let json = #"{"keys":[{"id":"K1","placed":false},{"id":"\#(legacy)","placed":true}],"version":1}"#
        let stored = try XCTUnwrap(CallKeyPriority.Stored.decode(Data(json.utf8)))
        XCTAssertEqual(stored.keys.map { $0.seq }, [0, 0])

        let backing = MemoryBacking()
        backing.data = Data(json.utf8)
        let held = Held()
        held.add("K1", .kms, at: 1)
        held.add(legacy, .other, at: 2, device: CallKeyPriority.inPersonDevice(ofAccount: legacy))
        let store = makeStore(backing, held)
        XCTAssertEqual(store.current().ids, ["K1", legacy], "the old entry is where the user left it")

        held.add(fresh, .other, at: 3, device: CallKeyPriority.inPersonDevice(ofAccount: fresh))
        XCTAssertEqual(store.current().ids, ["K1", fresh, legacy])
        XCTAssertTrue(store.current().isPlacedByHand(fresh))
        XCTAssertEqual(store.current().pending(legacy), .retiring)
        XCTAssertEqual(store.finalize(fresh).deleted, [legacy])
        XCTAssertEqual(store.current().ids, ["K1", fresh])
    }

    /// The same phone paired by the other method, and another phone, are other devices: new keys at the end.
    func testAKeyOfAnotherDeviceOrOfTheOtherMethodIsANewKeyAtTheEnd() {
        let proximity = inPersonName("prox", deviceHex, "11111111")
        let otherProximity = inPersonName("prox", "fedcba9876543210", "22222222")
        let nfc = inPersonName("nfc", deviceHex, "33333333")
        XCTAssertEqual(Set([CallKeyPriority.inPersonDevice(ofAccount: proximity),
                            CallKeyPriority.inPersonDevice(ofAccount: otherProximity),
                            CallKeyPriority.inPersonDevice(ofAccount: nfc)]).count, 3)

        let backing = MemoryBacking()
        let held = Held()
        held.add("K1", .kms, at: 1)
        held.add(proximity, .other, at: 2, device: CallKeyPriority.inPersonDevice(ofAccount: proximity))
        let store = makeStore(backing, held)
        _ = store.moveUp(proximity)
        XCTAssertEqual(store.current().ids, [proximity, "K1"])

        held.add(otherProximity, .other, at: 3, device: CallKeyPriority.inPersonDevice(ofAccount: otherProximity))
        held.add(nfc, .other, at: 4, device: CallKeyPriority.inPersonDevice(ofAccount: nfc))
        XCTAssertEqual(store.current().ids, [proximity, "K1", otherProximity, nfc])
        XCTAssertTrue(store.current().isPlacedByHand(proximity))
        XCTAssertFalse(store.current().isPlacedByHand(otherProximity))
        XCTAssertFalse(store.current().isPlacedByHand(nfc))
        XCTAssertEqual(store.current().pending(nfc), .none)
        XCTAssertFalse(store.current().hasWaitingKey)
    }

    func testTheDeviceAndTheNameOfAnInPersonKey() {
        XCTAssertEqual(CallKeyPriority.inPersonDevice(ofAccount: "nfc-0123456789abcdef-0a1b2c3d"), "nfc-0123456789abcdef")
        XCTAssertEqual(CallKeyPriority.inPersonDevice(ofAccount: "prox-0123456789abcdef"), "prox-0123456789abcdef")
        for notInPerson in ["", "nfc-", "prox-01ef", "nfc-0123456789ABCDEF", "nfc-0123456789abcdef-xyz",
                            "nfc-0123456789abcdef-0a1b2c3d-00", "kms-0123456789abcdef", "__callkeyprio.v1",
                            "nfc-0123456789abcdefg"] {
            XCTAssertNil(CallKeyPriority.inPersonDevice(ofAccount: notInPerson), notInPerson)
        }
        let fingerprint = String(repeating: "AB", count: 32)
        XCTAssertEqual(CallKeyPriority.inPersonAccountName(device: "prox-0123456789abcdef", keyFingerprint: fingerprint),
                       "prox-0123456789abcdef-abababab")
        XCTAssertEqual(CallKeyPriority.inPersonDevice(ofAccount: CallKeyPriority.inPersonAccountName(
            device: "nfc-0123456789abcdef", keyFingerprint: fingerprint)), "nfc-0123456789abcdef")
    }

    func testTheStoredFormKeepsTheSequenceNumbers() throws {
        var list = CallKeyPriority()
        list.add(id: "K1", group: .kms)
        list.add(id: "O1", group: .other)
        list.storeAsReplacement(id: "O2", device: "O1")
        let decoded = try XCTUnwrap(CallKeyPriority.Stored.decode(try XCTUnwrap(list.stored.encoded())))
        XCTAssertEqual(decoded, list.stored)
        XCTAssertEqual(decoded.keys.map { $0.id }, ["K1", "O2", "O1"])
        XCTAssertEqual(decoded.keys.map { $0.seq }, [1, 3, 2])
    }

    // MARK: - The evidence of a call (F2)

    private let phoneIdentity = Data(repeating: 0x42, count: 32)
    private let otherIdentity = Data(repeating: 0x43, count: 32)

    private func inPersonKey(_ name: String, _ fingerprint: String, bound: Data?) -> InPersonKeyFinalize.Key {
        InPersonKeyFinalize.Key(name: name, fingerprint: fingerprint, boundIdentityKey: bound)
    }

    private func round(sigOk: Bool = true, signer: Data? = nil, kcmac: Bool = true, selected: String? = nil,
                       blinded: Bool = false, matched: [String] = []) -> InPersonKeyFinalize.Round {
        InPersonKeyFinalize.Round(sigOk: sigOk, signerIdentityKey: sigOk ? (signer ?? phoneIdentity) : nil,
                                  kcmacVerified: kcmac, selectedFingerprint: selected,
                                  advertIsBlinded: blinded, matchedFingerprints: matched)
    }

    func testARoundThatSelectedTheNewKeyFinalizesIt() {
        let oldKey = inPersonKey("nfc-0123456789abcdef", "fp-old", bound: phoneIdentity)
        let newKey = inPersonKey("nfc-0123456789abcdef-22222222", "fp-new", bound: phoneIdentity)
        XCTAssertEqual(InPersonKeyFinalize.namesToFinalize(round: round(selected: "fp-new"), localKeys: [oldKey, newKey]),
                       [newKey.name], "(a) the agreed PSK is the new key")
        XCTAssertEqual(InPersonKeyFinalize.namesToFinalize(round: round(selected: "fp-old"), localKeys: [oldKey, newKey]),
                       [oldKey.name], "proving the old key finalizes nothing newer")
        XCTAssertEqual(InPersonKeyFinalize.namesToFinalize(round: round(selected: nil), localKeys: [oldKey, newKey]), [])
    }

    func testARoundThatMatchedTheNewKeyThroughAV3TagFinalizesItAStaticMatchDoesNot() {
        let oldKey = inPersonKey("prox-0123456789abcdef", "fp-old", bound: phoneIdentity)
        let newKey = inPersonKey("prox-0123456789abcdef-22222222", "fp-new", bound: phoneIdentity)
        // The old key is the one selected (it ranks first in the peer's advert); the new one matched too.
        let blinded = round(selected: "fp-old", blinded: true, matched: ["fp-old", "fp-new"])
        XCTAssertEqual(InPersonKeyFinalize.namesToFinalize(round: blinded, localKeys: [oldKey, newKey]),
                       [oldKey.name, newKey.name], "(b) the signed advert matched it through a tag")
        let staticAdvert = round(selected: "fp-old", blinded: false, matched: ["fp-old", "fp-new"])
        XCTAssertEqual(InPersonKeyFinalize.namesToFinalize(round: staticAdvert, localKeys: [oldKey, newKey]),
                       [oldKey.name], "a match against the static fingerprint does not count")
    }

    func testNothingFinalizesWithoutTheSignatureTheMacOrTheBoundIdentity() {
        let newKey = inPersonKey("nfc-0123456789abcdef-22222222", "fp-new", bound: phoneIdentity)
        XCTAssertEqual(InPersonKeyFinalize.namesToFinalize(round: round(selected: "fp-new"), localKeys: [newKey]), [newKey.name])
        XCTAssertEqual(InPersonKeyFinalize.namesToFinalize(round: round(sigOk: false, selected: "fp-new"), localKeys: [newKey]), [])
        XCTAssertEqual(InPersonKeyFinalize.namesToFinalize(round: round(kcmac: false, selected: "fp-new"), localKeys: [newKey]), [])
        XCTAssertEqual(InPersonKeyFinalize.namesToFinalize(
            round: round(signer: otherIdentity, selected: "fp-new"), localKeys: [newKey]), [], "signed by another device")
        let unbound = inPersonKey("nfc-0123456789abcdef-22222222", "fp-new", bound: nil)
        XCTAssertEqual(InPersonKeyFinalize.namesToFinalize(round: round(selected: "fp-new"), localKeys: [unbound]), [])
        let notInPerson = inPersonKey("K1", "fp-new", bound: phoneIdentity)
        XCTAssertEqual(InPersonKeyFinalize.namesToFinalize(round: round(selected: "fp-new"), localKeys: [notInPerson]), [])
    }

    /// A rekey this phone started resolves its ACCEPT against the vault: while it waits, nothing is deleted.
    func testFinalizationsAreHeldWhileARekeyWaitsForItsAcceptAndRunWhenItIsDoneOrTheCallEnds() {
        var deferred = DeferredInPersonFinalize()
        XCTAssertEqual(deferred.submit(callId: "CALL-1", names: ["new"], rekeyWaitingForAccept: true), [],
                       "held while the rekey waits")
        XCTAssertEqual(deferred.submit(callId: "call-1", names: ["new", "newer"], rekeyWaitingForAccept: true), [])
        // Another call is not affected.
        XCTAssertEqual(deferred.submit(callId: "call-2", names: ["x"], rekeyWaitingForAccept: false), ["x"])
        // The next verified round, with no rekey waiting, runs everything held, once.
        XCTAssertEqual(deferred.submit(callId: "call-1", names: [], rekeyWaitingForAccept: false), ["new", "newer"])
        XCTAssertEqual(deferred.flush(callId: "call-1"), [])

        XCTAssertEqual(deferred.submit(callId: "call-3", names: ["y"], rekeyWaitingForAccept: true), [])
        XCTAssertEqual(deferred.flush(callId: "CALL-3"), ["y"], "the call ends: what was held runs")
        XCTAssertEqual(deferred.flush(callId: "call-3"), [])
        XCTAssertEqual(deferred, DeferredInPersonFinalize())
    }

    /// The race itself: the key the rekey advertised is still in the vault when its ACCEPT is resolved.
    func testTheKeyAdvertisedByAWaitingRekeyIsStillHeldWhenTheCallEndsAndOnlyThenDeleted() {
        let backing = MemoryBacking()
        let held = Held()
        let oldName = "nfc-" + deviceHex
        let newName = inPersonName("nfc", deviceHex, "22222222")
        held.add(oldName, .other, at: 1, device: "nfc-" + deviceHex)
        let store = makeStore(backing, held)
        XCTAssertEqual(store.current().ids, [oldName])
        held.add(newName, .other, at: 2, device: "nfc-" + deviceHex)
        XCTAssertEqual(store.current().ids, [newName, oldName])

        var deferred = DeferredInPersonFinalize()
        for name in deferred.submit(callId: "c", names: [newName], rekeyWaitingForAccept: true) { store.finalize(name) }
        XCTAssertTrue(held.items.contains(where: { $0.id == oldName }), "the ACCEPT can still be resolved")
        for name in deferred.flush(callId: "c") { store.finalize(name) }
        XCTAssertEqual(held.items.map { $0.id }, [newName])
    }

    /// A call proves the old and the new key at once: finalizing in either order ends with the new key alone.
    func testFinalizingInEitherOrderEndsWithTheNewKeyAlone() {
        for reversed in [false, true] {
            let backing = MemoryBacking()
            let held = Held()
            let oldName = "nfc-" + deviceHex
            let newName = inPersonName("nfc", deviceHex, "22222222")
            held.add("K1", .kms, at: 1)
            held.add(oldName, .other, at: 2, device: "nfc-" + deviceHex)
            let store = makeStore(backing, held)
            XCTAssertEqual(store.current().ids, ["K1", oldName])
            held.add(newName, .other, at: 3, device: "nfc-" + deviceHex)
            XCTAssertEqual(store.current().ids, ["K1", newName, oldName])
            for name in reversed ? [newName, oldName] : [oldName, newName] {
                store.finalize(name)
            }
            XCTAssertEqual(store.current().ids, ["K1", newName], "reversed: \(reversed)")
        }
    }

    /// The loss the rule is made for: the new key was stored on one phone only. The other phone still holds the old
    /// key, and so does this one: the old key is live, advertised and selectable, and nothing was deleted.
    func testAfterALostMessageTheEarlierKeyIsStillInTheAdvertAndNothingIsDeleted() {
        let backing = MemoryBacking()
        let held = Held()
        let oldName = inPersonName("prox", deviceHex, "11111111")
        let newName = inPersonName("prox", deviceHex, "22222222")
        held.add("K1", .kms, at: 1)
        held.add(oldName, .other, at: 2, device: "prox-" + deviceHex)
        let store = makeStore(backing, held)
        XCTAssertEqual(store.current().ids, ["K1", oldName])
        held.add(newName, .other, at: 3, device: "prox-" + deviceHex)
        XCTAssertTrue(store.current().ids.contains(oldName))
        XCTAssertTrue(store.current().ids.contains(newName))
        // Time passes, the app restarts, the user opens Key management: still nothing deleted.
        let restarted = makeStore(backing, held)
        XCTAssertEqual(restarted.current().ids, ["K1", newName, oldName])
        XCTAssertEqual(held.items.count, 3)
    }

    func testAKeyDeletedFromTheVaultLeavesTheListAndLosesItsMark() {
        let backing = MemoryBacking()
        let held = Held()
        held.add("O1", .other, at: 1)
        held.add("K1", .kms, at: 2)
        let store = makeStore(backing, held)
        _ = store.moveUp("O1")

        held.remove("O1")
        XCTAssertEqual(store.current().ids, ["K1"])
        // The same name again is a new key: not placed, so the new KMS key goes above it.
        held.add("O1", .other, at: 5)
        held.add("K2", .kms, at: 6)
        XCTAssertEqual(store.current().ids, ["K2", "K1", "O1"])
        XCTAssertFalse(store.current().isPlacedByHand("O1"))
    }

    func testAStoredListThatCannotBeReadIsNeverOverwritten() throws {
        let backing = MemoryBacking()
        let held = Held()
        held.add("O1", .other, at: 1)
        held.add("K1", .kms, at: 2)
        let store = makeStore(backing, held)
        _ = store.moveUp("O1")
        let before = try XCTUnwrap(backing.data)
        let writesBefore = backing.writes

        backing.unreadable = true
        held.add("K2", .kms, at: 3)
        // The order shown while the store is unreadable is the first-run one, and nothing is written.
        XCTAssertEqual(store.current().ids, ["K2", "K1", "O1"])
        XCTAssertFalse(store.moveDown("K2").saved)
        XCTAssertEqual(backing.writes, writesBefore)
        XCTAssertEqual(backing.data, before)

        backing.unreadable = false
        XCTAssertEqual(store.current().ids, ["O1", "K2", "K1"])
    }

    /// The arrow press of Key management: when the new order cannot be stored the store says so (the screen shows its
    /// error banner), and the list it returns is the stored one, not the move that was lost.
    func testAMoveThatCannotBeStoredIsReportedAndLeavesTheStoredOrder() throws {
        let backing = MemoryBacking()
        let held = Held()
        held.add("O1", .other, at: 1)
        held.add("K1", .kms, at: 2)
        let store = makeStore(backing, held)
        XCTAssertEqual(store.current().ids, ["K1", "O1"])
        let stored = try XCTUnwrap(backing.data)

        backing.failWrites = true
        let refused = store.moveUp("O1")
        XCTAssertFalse(refused.saved)
        XCTAssertEqual(refused.list.ids, ["K1", "O1"])
        XCTAssertEqual(backing.data, stored)
        XCTAssertEqual(store.current().ids, ["K1", "O1"])
        XCTAssertFalse(store.moveDown("K1").saved)

        backing.failWrites = false
        let accepted = store.moveUp("O1")
        XCTAssertTrue(accepted.saved)
        XCTAssertEqual(accepted.list.ids, ["O1", "K1"])
        XCTAssertEqual(store.current().ids, ["O1", "K1"])
    }

    func testAMoveIsReportedAsNotStoredWhenTheStoredListCannotBeRead() {
        let backing = MemoryBacking()
        let held = Held()
        held.add("O1", .other, at: 1)
        held.add("K1", .kms, at: 2)
        let store = makeStore(backing, held)
        XCTAssertTrue(store.moveUp("O1").saved)
        let writes = backing.writes

        backing.unreadable = true
        let move = store.moveDown("O1")
        XCTAssertFalse(move.saved)
        XCTAssertEqual(backing.writes, writes)
    }

    func testAMoveThatNeedsNoWriteIsReportedAsStored() {
        let backing = MemoryBacking()
        let held = Held()
        held.add("K1", .kms, at: 1)
        let store = makeStore(backing, held)
        _ = store.moveUp("K1")
        let writes = backing.writes

        // A key that is not in the list changes nothing, so there is nothing to store and nothing is lost.
        backing.failWrites = true
        let move = store.moveUp("missing")
        XCTAssertTrue(move.saved)
        XCTAssertEqual(move.list.ids, ["K1"])
        XCTAssertEqual(backing.writes, writes)
    }

    func testAStoredListThatIsDamagedIsRebuiltAsTheFirstRun() {
        let backing = MemoryBacking()
        backing.data = Data("damaged".utf8)
        let held = Held()
        held.add("O1", .other, at: 1)
        held.add("K1", .kms, at: 2)
        let store = makeStore(backing, held)
        XCTAssertEqual(store.current().ids, ["K1", "O1"])
        XCTAssertEqual(backing.writes, 1)
        XCTAssertNotNil(backing.data.flatMap { CallKeyPriority.Stored.decode($0) })
    }

    // MARK: - Display and the cleanup of the removed entries

    func testShortFingerprintIsTheFirst64BitsInFourGroups() {
        let full = "0123456789abcdef" + String(repeating: "0", count: 48)
        XCTAssertEqual(CallKeyPriorityStore.shortFingerprint(label: full), "0123.4567.89ab.cdef")
        XCTAssertEqual(CallKeyPriorityStore.shortFingerprint(label: full.uppercased()), "0123.4567.89ab.cdef")
        XCTAssertEqual(CallKeyPriorityStore.shortFingerprint(label: "d00d.d00d.d00d.d00d"), "d00d.d00d.d00d.d00d")
        XCTAssertEqual(CallKeyPriorityStore.shortFingerprint(label: nil), "—")
        XCTAssertEqual(CallKeyPriorityStore.shortFingerprint(label: ""), "—")
    }

    func testOnlyTheRotatedEphemeralEntriesOfTheRemovedKeyRotationAreCleanedUp() {
        let names = [
            "peer.4fd0c1d8-0000-0000-0000-000000000001",
            "rotated_ephemeral.1784800000",
            "peer.alice",
            "nfc-0123456789abcdef",
            "prox-0123456789abcdef",
            "11111111-1111-1111-1111-111111111111",
            "__device.x25519.priv",
            "__callkeyprio.v1",
        ]
        let removed = LegacyIdentityKeyEntries.namesToRemove(from: names, origin: { name in
            // "peer.alice" was stored with an explicit manual origin: it is a key someone typed, not an identity entry.
            name == "peer.alice" ? .manual : PskOrigin.inferred(fromAccountName: name)
        })
        // The public keys of scanned contacts stay: they are no call keys and are not part of this cleanup.
        XCTAssertEqual(removed, ["rotated_ephemeral.1784800000"])
    }

    func testTheOrderEntryIsDeviceInternalSoItIsNeverACallKeyOrAdvertised() {
        XCTAssertEqual(PskOrigin.inferred(fromAccountName: VaultCallKeyPriorityBacking.accountName), .deviceInternal)
        XCTAssertFalse(PskAdvertising.isEligibleMatchCandidate(origin: .deviceInternal))
    }

    // MARK: - Protection of the order entry

    /// The order is metadata, not a secret: it is read on the main thread and while a call is being set up, so it
    /// must never carry the user-presence access control the keys take when biometric key protection is on.
    func testTheOrderEntryIsPinnedToAClassWithNoAccessControlAndTheKeysAreNot() {
        typealias Protection = SovereignKeyVault.EntryProtection
        XCTAssertEqual(Protection.forAccount(VaultCallKeyPriorityBacking.accountName), .deviceMetadata)
        XCTAssertEqual(Protection.deviceMetadata.pinnedAccessClass, .afterFirstUnlockThisDeviceOnly)
        XCTAssertNil(Protection.followsKeyPolicy.pinnedAccessClass)
        for name in [
            "11111111-1111-1111-1111-111111111111",
            "nfc-0123456789abcdef",
            "prox-0123456789abcdef",
            "__device.x25519.priv",
            "__kmsname.abcdef",
            "__kms.active_epoch.3",
        ] {
            XCTAssertEqual(Protection.forAccount(name), .followsKeyPolicy, name)
        }
    }

    #if canImport(Security)
    /// The attributes a write and a re-protection give the entry. The plain object below stands in for the
    /// `SecAccessControl` a key takes when biometric protection is on: the order must come out without it, a key
    /// with it.
    func testTheOrderEntryIsWrittenAfterFirstUnlockWithoutAnAccessControlEvenWhenKeysTakeOne() {
        let accessControl = NSObject()
        let afterFirstUnlock = kSecAttrAccessibleAfterFirstUnlockThisDeviceOnly as String

        for given in [accessControl, nil] as [NSObject?] {
            let order = SovereignKeyVault.protectionAttributes(
                forAccount: VaultCallKeyPriorityBacking.accountName, accessControl: given)
            XCTAssertNil(order[kSecAttrAccessControl as String])
            XCTAssertEqual(order[kSecAttrAccessible as String] as? String, afterFirstUnlock)
            XCTAssertEqual(order.count, 1)
        }

        let protectedKey = SovereignKeyVault.protectionAttributes(
            forAccount: "nfc-0123456789abcdef", accessControl: accessControl)
        XCTAssertNotNil(protectedKey[kSecAttrAccessControl as String])
        XCTAssertNil(protectedKey[kSecAttrAccessible as String])

        let plainKey = SovereignKeyVault.protectionAttributes(forAccount: "nfc-0123456789abcdef", accessControl: nil)
        XCTAssertNil(plainKey[kSecAttrAccessControl as String])
        let plainClass = KeychainAccessibilityPolicy.secAttrAccessible(for: .sessionPsk) as String
        XCTAssertEqual(plainKey[kSecAttrAccessible as String] as? String, plainClass)
    }
    #endif

    // MARK: - No notification inside the lock

    /// `CallKeyPriorityStore` writes the order while it holds its lock, on the thread that asked, the main thread
    /// included. A vault notification posted from there would run the block observers inside the critical section,
    /// and an observer registered on another queue makes the poster wait for that queue. The write of the order
    /// therefore must not be announced. (The Keychain test in `SovereignKeyVaultNotificationTests` runs the real
    /// write; this one pins the rule the vault applies, without a Keychain.)
    func testTheWriteOfTheOrderIsNotAnnouncedOnTheVaultNotification() {
        XCTAssertFalse(SovereignKeyVault.announcesChange(ofAccount: VaultCallKeyPriorityBacking.accountName))
    }

    func testOnlyTheKeysAUserCanSeeAreAnnounced() {
        XCTAssertTrue(SovereignKeyVault.announcesChange(ofAccount: "11111111-1111-1111-1111-111111111111"))
        XCTAssertTrue(SovereignKeyVault.announcesChange(ofAccount: "nfc-0123456789abcdef"))
        XCTAssertTrue(SovereignKeyVault.announcesChange(ofAccount: "prox-0123456789abcdef"))
        XCTAssertFalse(SovereignKeyVault.announcesChange(ofAccount: "__device.x25519.priv"))
        XCTAssertFalse(SovereignKeyVault.announcesChange(ofAccount: "__kmsname.abcdef"))
    }
}
